assert len(SCREENS)==100,(len(SCREENS),set(BYFILE)-{Path(s['source']).name for s in SCREENS})
assert {s['source'] for s in SCREENS}=={r['source'] for r in AUDIT}

# Review states preserve native distinctions; they are not extra counted screens.
for s in SCREENS:
    title=s['name'];body=s['content'];foot=s['footer'];variants=s['variants']
    variants.setdefault('loading',v('<div class="loading-sample" aria-label="جار التحميل">'+''.join('<div class="skeleton"></div>' for _ in range(5))+'<p>جار تحميل البيانات…</p></div>'))
    if s['kind'] in ['form','action','payment','signing']:
        variants.setdefault('error',v(note('تعذّر إكمال الخطوة. بياناتك محفوظة في المعاينة؛ راجعها وحاول مرة أخرى.','error','help')+body,foot))
        blocked='<fieldset disabled class="batch-blocked">'+body+'</fieldset>'
        variants.setdefault('saving',v(note('جار تنفيذ الخطوة. لا تكرر الإرسال.','info','clock')+blocked))
        variants.setdefault('unknown-outcome',v(note('لم تتأكد نتيجة العملية. راجع المحاولة الأصلية قبل أي إرسال جديد.','warning','clock')+blocked,footer('مراجعة العملية الأصلية','batch-recover')))
    else:
        variants.setdefault('error',v(intro('تعذّر تحميل البيانات.','راجع الاتصال وحاول من جديد.',True,'help')+button('إعادة المحاولة',action='reset-state',kind='primary wide')))
        variants.setdefault('stale',v(note('هذه آخر بيانات معروضة. حدّثها قبل اتخاذ أي إجراء.','warning','clock')+panel('<h3>'+title+'</h3><p class="small">النسخة الحالية تحتاج مراجعة من جديد.</p>')+button('تحديث البيانات',action='reset-state',kind='primary wide')))
        variants.setdefault('restricted',v(intro('الإجراء غير متاح حاليًا.','الصلاحيات والحالة الحالية تحددان ما يمكنك متابعته.',True,'lock')+button('مراجعة الحالة',action='reset-state',kind='secondary wide')))
    if 'empty' in s['requiredStates']:
        variants.setdefault('empty',v(intro('لسه مفيش بيانات هنا.','هتظهر البيانات المتاحة لهذا الحساب في المكان ده.',True,'file')+button('تحديث',action='reset-state',kind='secondary wide')))
    for state in s['requiredStates']:
        if state in variants or state in ['dirty','invalid']:continue
        if state in ['permission-denied','unsupported','policy-unsupported','unavailable','signing-unavailable','delivery-unavailable']:
            variants[state]=v(intro('الخطوة غير متاحة حاليًا.','راجع الإذن أو إتاحة الخدمة قبل المتابعة.',True,'help')+button('مراجعة الحالة',action='reset-state',kind='secondary wide'))
        elif state in ['conflict','revision-changed','source-changed','inventory-changed','quote-changed','criteria-review']:
            variants[state]=v(note('التفاصيل أو النسخة اتغيّرت. راجع البيانات الحالية قبل تأكيد قرارك.','warning','file')+panel('<h3>'+title+'</h3><p class="small">لا تستخدم النسخة السابقة لإرسال إجراء جديد.</p>')+button('تحميل النسخة الحالية',action='reset-state',kind='primary wide'))
        elif state in ['expired','session-ended','self-action-blocked','read-only','legacy-read-only','unsafe']:
            wording={'expired':'انتهت صلاحية هذه الخطوة.','session-ended':'انتهت الجلسة.','self-action-blocked':'لا يمكن تنفيذ الإجراء على حسابك نفسه.','read-only':'هذه النسخة للقراءة فقط.','legacy-read-only':'سجل سابق للقراءة فقط.','unsafe':'المرفق غير متاح للعرض.'}[state]
            variants[state]=v(intro(wording,'راجع الحالة الحالية من المصدر قبل المتابعة.',True,'lock')+button('مراجعة الحالة',action='reset-state',kind='secondary wide'))
        elif state in ['processing','scanning']:
            variants[state]=v(intro('الخطوة قيد المعالجة.','البيانات ليست جاهزة للاعتماد بعد.',True,'clock')+'<div class="coverage-meter"><span style="width:55%"></span></div>'+button('مراجعة الحالة',action='reset-state',kind='secondary wide'))
        elif state in ['paid','signed','accepted']:
            variants[state]=v(intro({'paid':'تحصيل مؤكّد · مثال','signed':'نسخة موقّعة · مثال','accepted':'مقبولة · مثال'}[state],'حالة توضيحية؛ النتيجة الفعلية تعتمد على السجل المعتمد.',True,'check')+summary([('المرجع','مثال توضيحي'),('السجل','الحالة مؤكدة في هذا المثال فقط')]))
        elif state in ['fulfillment-pending','extension-pending','grace','chargeback','availability-unknown','partial-error','no-baseline','evidence-missing','no-selectable-output','cancelled','delivery-unknown']:
            copy={'fulfillment-pending':'تمت مراجعة الدفع، والتفعيل لم يتأكد بعد.','extension-pending':'طلب المهلة في انتظار المراجعة.','grace':'فترة سماح حسب سجل الاشتراك.','chargeback':'العملية محل مراجعة اعتراض مالي.','availability-unknown':'إتاحة العقار لم تتأكد بعد.','partial-error':'بعض الاختيارات لم يكتمل تحميلها.','no-baseline':'لا يوجد تقرير دخول مرجعي متاح.','evidence-missing':'أعد اختيار المرفقات المطلوبة قبل المتابعة.','no-selectable-output':'لا توجد مخرجات جاهزة للاختيار.','cancelled':'تم إلغاء مهمة البحث في هذا المثال.','delivery-unknown':'حالة تسليم الرسالة غير مؤكدة.'}[state]
            variants[state]=v(note(copy,'warning','clock')+panel('<h3>'+title+'</h3><p class="small">راجع التفاصيل المطلوبة قبل أي إجراء جديد.</p>')+button('مراجعة الحالة',action='reset-state',kind='secondary wide'))
    # All rendered states are declared separately from additional native-only states.
    s['renderedStatePolicy']='Primary mockup plus explicitly labelled local review variants. Native dirty/invalid validation uses the form, not a separate counted screen.'

for number in range(3,8):
    batch=sorted([s for s in SCREENS if s['sprint']==number],key=lambda s:int(s['id'][1:]))
    assert len(batch)==20
    out=HERE/f'sprint-{number:02}'
    render(batch,number,out,(HERE/'sprint02.css').read_text()+'\n'+(HERE/'batch03_07.css').read_text())
    docs=[f'# Sprint {number} — {batch[0]["id"]}–{batch[-1]["id"]}','','This sprint belongs to the authorized five-sprint batch (3–7). Stop after Sprint 7 for user review. No Flutter or API behavior changes.','','## Visual authority','','Original S01–S20, Readex/Plex type, pine/paper tokens, original control/card proportions and selective signature headers. All data, dates, balances, model previews and messages are illustrative. Maps/capture/provider/signature prototypes never use real device services or external APIs.','','## Source audit','','Every primary file and dependency below was inspected from the sibling `sokoun` checkout. `../batch-03-07-source-audit.json` records source hashes, label keys, commands and guards. A screen count represents a distinct source destination; its data/permission/provider variants do not inflate the count.','','## Common contract','','Freshness, role/capability, source revision, command identity and uncertain-write recovery remain authoritative. Private data stays scoped to session/workspace. Prototype confirmations only demonstrate intent: they do not assert payment, publication, signatures, consent for other users, refunds, occupancy or liability. A readonly or stale variant must not contain a mutating control.','','## Screen audit','']
    for s in batch:
        docs += [f'<a id="{s["id"].lower()}"></a>',f'### {s["id"]} — {s["english"]}','',f'Source: `{s["source"]}`','',s['behavior'],'','Original visual references: '+', '.join(s['visualReference'])+'.','','Required implementation states: '+', '.join(s['requiredStates'])+'.','','Rendered review variants: '+', '.join(s['variants'])+'.','','Dependencies: '+', '.join('`'+d['source']+'`' for d in s['dependencies'])+'.','']
    (out/'AUDIT.md').write_text('\n'.join(docs)+'\n')
    (out/'README.md').write_text(f'# Sprint {number} — {batch[0]["id"]}–{batch[-1]["id"]}\n\n[Open the 20 mockups](index.html) · [All screens](../../index.html) · [Behavior audit](AUDIT.md)\n\nPart of the five-sprint batch 3–7. Light/Dark/System, source-linked manifests, local workflow states and image exports. All data and actions are illustrative. Native device, API, provider and permission checks remain required during implementation.\n\nReview all five sprints before proceeding to Sprint 8.\n')
    print(f'Built Sprint {number}: {batch[0]["id"]}–{batch[-1]["id"]}, 20 screens')
